<script>
import Layout from "../../../layouts/main";
import appConfig from "@/app.config";
import PageHeader from "@/components/page-header";
export default {
  page: {
    meta: [
      {
        name: "description",
        content: appConfig.description,
      },
    ],
  },
  components: {
    Layout,
    PageHeader,
  },
  data() {
    return {
      fixedAssetsClasses: [],
      fixedAssetsSubClasses: [],
      cls: {},
    };
  },
  methods: {
    // fixed assets class methods
    addFixedAssetClass() {
      var data = {
        title: "popups.add",
        inputs: [
          { model: "name", type: "text", label: "fixed_assets.label" },
          { model: "name_en", type: "text", label: "fixed_assets.label_en" },
        ],
        buttons: [
          {
            text: "popups.add",
            closer: true,
            color: "primary",
            handler: (obj) => {
              obj.branch_id = this.branch_id;
              this.http.post("fixed-assets/classes", obj).then(() => {
                this.getFixedAssetsClasses();
              });
            },
          },
          {
            text: "popups.cancel",
            closer: true,
            color: "danger",
            handler: () => {
              console.log("Like Clicked");
            },
          },
        ],
      };
      this.popup.modal(data);
    },
    editFixedAssetClass(cls) {
      var data = {
        title: "popups.edit",
        inputs: [
          {
            model: "name",
            type: "text",
            label: "fixed_assets.label",
            value: cls.name,
          },
          {
            model: "name_en",
            type: "text",
            label: "fixed_assets.label_en",
            value: cls.name_en,
          },
        ],
        buttons: [
          {
            text: "popups.edit",
            closer: true,
            color: "primary",
            handler: (obj) => {
              this.http.put("fixed-assets/classes", cls.id, obj).then(() => {
                this.getFixedAssetsClasses();
              });
            },
          },
          {
            text: "popups.cancel",
            closer: true,
            color: "danger",
            handler: () => {
              console.log("Like Clicked");
            },
          },
        ],
      };
      this.popup.modal(data);
    },
    deleteFixedAssetClass(cls) {
      var data = {
        title: "popups.delete",
        msg: "popups.delmessage",
      };
      this.popup.confirm(data).then((resp) => {
        if (resp) {
          this.http.delete("fixed-assets/classes", cls.id).then(() => {
            this.getFixedAssetsClasses();
          });
        }
      });
    },
    getFixedAssetsClasses() {
      this.http.get("fixed-assets/classes").then((res) => {
        this.fixedAssetsClasses = res.data;
      });
    },
    getFixedAssetSubClasses(cls) {
      this.cls = cls;
      this.http.get("fixed-assets/subclasses/" + cls.id).then((res) => {
        this.fixedAssetsSubClasses = res.data;
      });
    },

    // fixed assets subclass methods
    addFixedAssetSubClass() {
      document.querySelectorAll(".btn-close").forEach((btn) => btn.click());
      setTimeout(() => {
        var data = {
          title: "popups.add",
          inputs: [
            { model: "name", type: "text", label: "fixed_assets.label" },
            { model: "name_en", type: "text", label: "fixed_assets.label_en" },
          ],
          buttons: [
            {
              text: "popups.add",
              closer: true,
              color: "primary",
              handler: (obj) => {
                obj.branch_id = this.branch_id;
                this.http
                  .post("fixed-assets/subclasses/" + this.cls.id, obj)
                  .then(() => {
                    this.getFixedAssetsClasses();
                  });
              },
            },
            {
              text: "popups.cancel",
              closer: true,
              color: "danger",
              handler: () => {
                console.log("Like Clicked");
              },
            },
          ],
        };
        this.popup.modal(data);
      }, 100);
    },
    editFixedAssetSubClass(cls) {
      document.querySelectorAll(".btn-close").forEach((btn) => btn.click());
      setTimeout(() => {
        var data = {
          title: "popups.edit",
          inputs: [
            {
              model: "name",
              type: "text",
              label: "fixed_assets.label",
              value: cls.name,
            },
            {
              model: "name_en",
              type: "text",
              label: "fixed_assets.label_en",
              value: cls.name_en,
            },
          ],
          buttons: [
            {
              text: "popups.edit",
              closer: true,
              color: "primary",
              handler: (obj) => {
                this.http
                  .put("fixed-assets/subclasses", cls.id, obj)
                  .then(() => {});
              },
            },
            {
              text: "popups.cancel",
              closer: true,
              color: "danger",
              handler: () => {
                console.log("Like Clicked");
              },
            },
          ],
        };
        this.popup.modal(data);
      }, 300);
    },
    deleteFixedAssetSubClass(cls) {
      document.querySelectorAll(".btn-close").forEach((btn) => btn.click());
      setTimeout(() => {
        var data = {
          title: "popups.delete",
          msg: "popups.delmessage",
        };
        this.popup.confirm(data).then((resp) => {
          if (resp) {
            this.http.delete("fixed-assets/subclasses", cls.id).then(() => {
              this.getFixedAssetsClasses();
            });
          }
        });
      }, 300);
    },
  },
  created() {
    this.getFixedAssetsClasses();
  },
};
</script>
